import json, sys, collections

def aggregate():
    try:
        with open('records.jsonl', 'r') as f:
            records = [json.loads(line) for line in f]
    except FileNotFoundError:
        return
    user_totals = collections.defaultdict(lambda: {'amount': 0.0, 'items': 0})
    tag_counts = collections.defaultdict(int)
    for r in records:
        user = r.get('user', 'unknown')
        amount = float(r.get('amount', 0))
        user_totals[user]['amount'] += amount
        user_totals[user]['items'] += r.get('items', 0)
        for tag in r.get('tags', []):
            tag_counts[tag] += 1
    top_users = sorted(user_totals.items(), key=lambda x: (-x[1]['amount'], x[0]))[:5]
    top_tags = sorted(tag_counts.items(), key=lambda x: (-x[1], x[0]))[:5]
    output = {
        'top_users': [{'user': u, 'amount': round(d['amount'], 2), 'items': d['items']}] for u, d in top_users],
        'top_tags': [{'tag': t, 'count': c}] for t, c in top_tags]
    }
    with open('aggregates.json', 'w') as f:
        json.dump(output, f, indent=2)

if __name__ == '__main__':
    try:
        aggregate()
    except Exception as e:
        print(f'Error: {e}', file=sys.stderr)
        sys.exit(1)

